INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind analoge Daten immer physisch messbar?', 2, '[{"text": "Ja", "correct": true, "because": "Stammen aus kontinuierlichen Signalen"}, {"text": "Nein", "correct": false, "because": "Typischerweise physikalisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaft haben analoge Daten?', 3, '[{"text": "Kontinuierlich", "correct": true, "because": "Fließende Werte"}, {"text": "Diskret", "correct": false, "because": "Eigenschaft digitaler Daten"}, {"text": "Statisch", "correct": false, "because": "Dynamisch veränderbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beispiele gehören zu analogen Daten?', 5, '[{"text": "Temperaturverlauf", "correct": true, "because": "Kontinuierliche Messung"}, {"text": "Tonwellen", "correct": true, "because": "Analoge Schwingungen"}, {"text": "Binärcode", "correct": false, "because": "Digital"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Analoge Daten haben unendlich viele Werte. b) Sie sind direkt digital verarbeitbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Brauchen Digitalisierung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Verarbeitung analoger Daten?', 4, '[{"text": "Signalqualität", "correct": false, "because": "Beeinflusst Ergebnisse"}, {"text": "Digitalisierung", "correct": false, "because": "Notwendig für Computer"}, {"text": "Farbe des Sensors", "correct": true, "because": "Irrelevant für Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob analoge Daten verrauscht sein können?', 2, '[{"text": "Ja", "correct": true, "because": "Störungen möglich"}, {"text": "Nein", "correct": false, "because": "Empfindlich für Rauschen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie nutze ich für analoge Daten?', 3, '[{"text": "Analoge Sensoren", "correct": true, "because": "Erfassen kontinuierliche Signale"}, {"text": "Binäre Speicher", "correct": false, "because": "Für digitale Daten"}, {"text": "Cloud-Speicher", "correct": false, "because": "Digital erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Umwandlung analoger Daten?', 5, '[{"text": "Analog-Digital-Wandler", "correct": true, "because": "Macht sie computerlesbar"}, {"text": "Abtastung", "correct": true, "because": "Diskretisiert Signale"}, {"text": "Direkte Speicherung", "correct": false, "because": "Braucht Konvertierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Analoge Daten sind präziser als digitale. b) Sie sind einfacher zu speichern. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Speicherung komplexer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei analogen Daten unwichtig?', 4, '[{"text": "Signalstärke", "correct": false, "because": "Beeinflusst Qualität"}, {"text": "Rauschfilterung", "correct": false, "because": "Verbessert Daten"}, {"text": "Dateiformat", "correct": true, "because": "Digitaler Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind analoge Daten direkt verarbeitbar?', 2, '[{"text": "Nein", "correct": true, "because": "Brauchen Digitalisierung"}, {"text": "Ja", "correct": false, "because": "Nur analog nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile haben analoge Daten?', 4, '[{"text": "Hohe Genauigkeit", "correct": true, "because": "Kontinuierliche Werte"}, {"text": "Natürliche Darstellung", "correct": true, "because": "Direkte Messung"}, {"text": "Einfache Speicherung", "correct": false, "because": "Komplexer"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass analoge Daten veraltet sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Immer noch in Sensorik relevant"}, {"text": "Ja", "correct": false, "because": "Nicht überholt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei analogen Daten?', 3, '[{"text": "Signalqualität", "correct": true, "because": "Entscheidet über Nutzen"}, {"text": "Speichergröße", "correct": false, "because": "Digitaler Faktor"}, {"text": "Verarbeitungsgeschwindigkeit", "correct": false, "because": "Nach Digitalisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Analoge Daten kommen aus der realen Welt. b) Sie sind immer verrauscht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Rauschen nicht zwangsläufig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile haben analoge Daten?', 5, '[{"text": "Rauschanfälligkeit", "correct": true, "because": "Störungen beeinträchtigen"}, {"text": "Schwere Speicherung", "correct": true, "because": "Braucht Umwandlung"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei analogen Daten unwichtig?', 3, '[{"text": "Abtastrate", "correct": false, "because": "Wichtig bei Digitalisierung"}, {"text": "Signalverstärkung", "correct": false, "because": "Verbessert Qualität"}, {"text": "Softwareversion", "correct": true, "because": "Digitaler Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Müssen analoge Daten digitalisiert werden?', 3, '[{"text": "Ja", "correct": true, "because": "Für Computer nötig"}, {"text": "Nein", "correct": false, "because": "Nur für digitale Verarbeitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob analoge Daten in Echtzeit genutzt werden können?', 2, '[{"text": "Ja", "correct": true, "because": "Direkt messbar"}, {"text": "Nein", "correct": false, "because": "Nicht eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gerät wähle ich für analoge Daten?', 4, '[{"text": "Mikrofon", "correct": true, "because": "Erfasst Tonwellen"}, {"text": "Festplatte", "correct": false, "because": "Digitaler Speicher"}, {"text": "Monitor", "correct": false, "because": "Anzeige, kein Sensor"}]');
